{
  "name": "slot_captions",
  "private": true,
  "type": "module",
  "scripts": {
    "build-cues": "node build_cues.mjs",
    "dev": "npx --yes hyperframes@0.8.3 preview",
    "check": "npx --yes hyperframes@0.8.3 check",
    "render": "npx --yes hyperframes@0.8.3 render",
    "publish": "npx --yes hyperframes@0.8.3 publish"
  }
}

// Build step: reads the project-level caption_cues.json (already computed on the
// OUTPUT/edited timeline) and emits cues.js — a plain JS array baked into the
// composition at build time. This keeps the HyperFrames HTML free of a
// render-time network fetch (determinism rule) while avoiding hand-authoring
// 588 timed elements.
//
// Overlap handling: caption_cues.json has a handful (4/588) of cues whose
// start/end slightly overlap the neighbor (source ASR chunking artifact).
// Since only one caption pill is ever shown at a time, we clip each cue's
// effective end to the next cue's start so two pills never render together.
//
// Run: node build_cues.mjs   (writes ./cues.js)

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const SRC = join(__dirname, "..", "..", "caption_cues.json");
const OUT = join(__dirname, "cues.js");

const raw = JSON.parse(readFileSync(SRC, "utf-8"));
if (!Array.isArray(raw) || raw.length === 0) {
  throw new Error("caption_cues.json is empty or not an array");
}

// Sort defensively by start time, then clip overlaps against the next cue.
const sorted = raw
  .map((c) => ({ start: Number(c.start), end: Number(c.end), text: String(c.text) }))
  .sort((a, b) => a.start - b.start);

const cues = sorted.map((c, i) => {
  const next = sorted[i + 1];
  let end = c.end;
  if (next && next.start < end) end = next.start;
  if (end <= c.start) end = c.start + 0.05; // guarantee a minimum visible sliver
  return { s: Math.round(c.start * 1000) / 1000, e: Math.round(end * 1000) / 1000, t: c.text };
});

const lastEnd = cues[cues.length - 1].e;
const duration = Math.round((lastEnd + 1) * 100) / 100;

const banner = `// AUTO-GENERATED by build_cues.mjs from ../../caption_cues.json — do not hand-edit.
// ${cues.length} cues, last cue ends at ${lastEnd}s, suggested composition duration ${duration}s.
`;
const body = `var CUES = ${JSON.stringify(cues)};\nvar CUES_DURATION = ${duration};\n`;

writeFileSync(OUT, banner + body, "utf-8");
console.log(`Wrote ${OUT}`);
console.log(`cues=${cues.length} lastEnd=${lastEnd} suggestedDuration=${duration}`);

